import data from "./timeline.json";

// Generated by scripts/build_motion_audio.py together with the (music-free) soundtrack.
export type MSceneId = "hook" | "brand" | "group" | "transformation" | "cta";

export const MT = data as {
  fps: number;
  durationSeconds: number;
  scenes: { id: MSceneId; start: number; end: number }[];
  endCardAt: number;
  logoHit: number;
  voLines: { id: MSceneId; start: number; end: number; text: string }[];
  words: { text: string; start: number; end: number }[];
};

const FPS = 30;
export const msec = (s: number) => Math.round(s * FPS);
export const M_DURATION = msec(MT.durationSeconds);

export const mscene = (id: MSceneId) => {
  const s = MT.scenes.find((x) => x.id === id)!;
  return { from: msec(s.start), duration: msec(s.end) - msec(s.start), start: s.start };
};

/** Scene-relative frame at which the n-th occurrence of a spoken word starts. */
export const mword = (scene: MSceneId, text: string, occurrence = 0) => {
  const hits = MT.words.filter((w) => w.text.replace(/[،.…!]/g, "") === text);
  if (!hits[occurrence]) throw new Error(`VO word "${text}" #${occurrence} not found`);
  return msec(hits[occurrence].start) - mscene(scene).from;
};

/** Scene-relative frame of an absolute time in seconds. */
export const mlocal = (scene: MSceneId, seconds: number) => msec(seconds) - mscene(scene).from;
